import {D1WorkLogRepository} from "../../src/work-log/repositories.js";
import {D1ExportRepository} from "../../src/work-log/export-storage.js";
import {ExportService,MemoryArtifactStore} from "../../src/work-log/export-core.generated.js";
import {WorkLogHttpService} from "../../src/work-log/http-service.generated.js";
const artifacts=new MemoryArtifactStore();
let ready;
const migrate=(db)=>db.exec(`CREATE TABLE IF NOT EXISTS work_logs(log_id TEXT PRIMARY KEY,subject_id TEXT NOT NULL,local_date TEXT NOT NULL,timezone TEXT,title TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '',project_id TEXT,project_name_snapshot TEXT,status TEXT NOT NULL,version INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,finalized_at INTEGER,deleted_at INTEGER,delete_after INTEGER);CREATE TABLE IF NOT EXISTS work_log_items(item_id TEXT PRIMARY KEY,log_id TEXT NOT NULL,subject_id TEXT NOT NULL,category TEXT,title TEXT NOT NULL,content TEXT,result TEXT,note TEXT,start_at TEXT,end_at TEXT,sort_order INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,deleted_at INTEGER);CREATE TABLE IF NOT EXISTS work_log_item_captures(subject_id TEXT NOT NULL,item_id TEXT NOT NULL,capture_id TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);CREATE TABLE IF NOT EXISTS export_jobs(export_id TEXT PRIMARY KEY,subject_id TEXT NOT NULL,client_export_id TEXT NOT NULL,query_digest TEXT NOT NULL,format TEXT NOT NULL,status TEXT NOT NULL,query_json TEXT NOT NULL,artifact_key TEXT,filename TEXT,content_type TEXT,size_bytes INTEGER,record_count INTEGER,created_at INTEGER NOT NULL,started_at INTEGER,ready_at INTEGER,expires_at INTEGER,error_code TEXT,UNIQUE(subject_id,client_export_id));`);
export default{async fetch(request,env){ready||=migrate(env.PROVENANCE_D1);await ready;const repository=new D1WorkLogRepository(env.PROVENANCE_D1),exportService=new ExportService({repository,jobs:new D1ExportRepository(env.PROVENANCE_D1),artifacts});return new WorkLogHttpService({repository,enabled:true,exportEnabled:true,exportService,authenticate:async(req)=>req.headers.get("authorization")==="Bearer creator"?{subjectId:"sub_export_d1",authType:"CREATOR"}:null}).handle(request)}};
